"""The command line of the interface (api.py): every method of `Evaluation` is a command with the same name, generated by autoresearch/suitecli.py from the signatures. The Evaluation is the
one front door: what has to execute the network (`run`, `tap`, `time`, `probe`) it passes to the Runner (runner_api.py, the layer below; its own command line is runsuite's).
`python -m evalsuite run runs/t23_C_s1 small.val --gt-key v8`, `show-numbers t23_C_s1@e3f9a2c1d4b0 --match drivable`, `compare A B` (b - a); `draw-frame` is `draw_frame`.
Every method also works with the class name (`Evaluation.run`); `Evaluation.list`, `Evaluation.probe`, `Evaluation.selftest` need it (older commands of cli.py have these words). A parameter without
a default (and `network`, `id`, `results`, `a`, `b`, `frame`, `frames`) is positional, every other one an option (`--gt-key v8`, `--workers 0`, `--metrics maps,boxes,curves` for a list).
`--project` names the project folder (default AR_PROJECT), `--adapter` its adapter module, `--json` prints exactly what the method returns (nothing else on stdout: progress goes to
stderr), otherwise a short text. `methods` lists the methods. Exit code: 0 ok, 1 `check` found problems, 2 an error (the message goes to stderr; EVALSUITE_TRACEBACK=1 shows the traceback)."""
from __future__ import annotations

import suitecli

from .api import Evaluation, EvaluationError

LEGACY = ("list", "probe", "selftest", "selftest-adapter")                # words of the older command line (cli.py): they need `Evaluation.` here
POSITIONAL = ("network", "id", "results", "a", "b", "frame", "frames")          # the things a command is about: positional even when they have a default (`run NETWORK SET`)

CLI = suitecli.Cli(Evaluation, "evalsuite", EvaluationError, "EVALSUITE_TRACEBACK", legacy=LEGACY, positional=POSITIONAL,
                   extra=(("--adapter", "the adapter module (default: <project>/evaluation/evalsuite.json)"),), make=lambda cls, a: cls(a.project, a.adapter))


def methods_text() -> None:
    CLI.methods_text()


def dispatch(argv):
    """the exit code when argv names a method of the Evaluation (`Evaluation.run`, `run`, `draw-frame`; `methods`), else None"""
    return CLI.dispatch(argv)


_clean = suitecli.clean                                                          # the self-test pins the json conversion
